6	#[derive(Debug)]
7	pub struct Interface {
8	    pub attrs: Vec<syn::Attribute>,
9	    pub token: interface,
10	    pub name: syn::Ident,
11	    pub generics: syn::Generics,
12	    pub requires: Vec<syn::Path>,
13	    pub methods: Vec<Method>,
14	    pub winrt: bool,
15	}
16	
17	impl syn::parse::Parse for Interface {
18	    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
19	        let attrs = input.call(syn::Attribute::parse_outer)?;
20	        let token = input.parse()?;
21	        let name = input.parse()?;
22	        let generics = input.parse()?;
23	
24	        let requires = if input.parse::<syn::Token![:]>().is_ok() {
25	            let mut requires = vec![input.parse::<syn::Path>()?];
26	            while input.parse::<syn::Token![+]>().is_ok() {
27	                requires.push(input.parse::<syn::Path>()?);
28	            }
29	            requires
30	        } else {
31	            vec![]
32	        };
33	
34	        let content;
35	        syn::braced!(content in input);
36	        let mut methods = vec![];
37	
38	        while !content.is_empty() {
39	            methods.push(content.parse()?);
40	        }
41	
42	        Ok(Self {
43	            attrs,
44	            token,
45	            name,
46	            generics,
47	            requires,
48	            methods,
49	            winrt: false,
50	        })
51	    }
52	}
53	
54	impl Encoder<'_> {
55	    pub fn encode_interface(&mut self, item: &Interface) -> Result<(), Error> {
56	        let mut flags = metadata::TypeAttributes::Public
57	            | metadata::TypeAttributes::Abstract
58	            | metadata::TypeAttributes::Interface;
59	
60	        if item.winrt {
61	            flags |= metadata::TypeAttributes::WindowsRuntime;
62	        }
63	
64	        let mut generics = Vec::with_capacity(item.generics.params.len());
65	        for generic in item.generics.params.iter() {
66	            let syn::GenericParam::Type(generic) = generic else {
67	                return self.err(generic, "only type generic parameters are supported");
68	            };
69	            generics.push(generic.ident.to_string());
70	        }
71	        self.generics = generics;
72	
73	        let mut name = self.name.to_string();
74	
75	        if !self.generics.is_empty() {
76	            name = format!("{name}`{}", self.generics.len());
77	        }
78	
79	        let interface = self.output.TypeDef(
80	            self.namespace,
81	            &name,
82	            metadata::writer::TypeDefOrRef::default(),
83	            flags,
84	        );
85	
86	        for (number, name) in self.generics.iter().enumerate() {
87	            self.output.GenericParam(
88	                name,
89	                metadata::writer::TypeOrMethodDef::TypeDef(interface),
90	                number.try_into().unwrap(),
91	                metadata::GenericParamAttributes::None,
92	            );
93	        }
94	
95	        self.encode_attrs(
96	            metadata::writer::HasAttribute::TypeDef(interface),
97	            &item.attrs,
98	            &["guid", "no_guid"],
99	        )?;
100	
101	        let already_has_guid = self.encode_guid_pseudo_attrs(
102	            metadata::writer::HasAttribute::TypeDef(interface),
103	            &item.attrs,
104	        )?;
105	
106	        if !item.winrt && item.requires.len() > 1 {
107	            return self.err(
108	                &item.requires[1],
109	                "non-WinRT interface can only inherit from one interface",
110	            );
111	        }
112	
113	        for require in &item.requires {
114	            let ty = self.encode_path(require)?;
115	            self.output.InterfaceImpl(interface, &ty);
116	        }
117	
118	        let base_flags = metadata::MethodAttributes::Public
119	            | metadata::MethodAttributes::HideBySig
120	            | metadata::MethodAttributes::Abstract
121	            | metadata::MethodAttributes::NewSlot
122	            | metadata::MethodAttributes::Virtual;
123	
124	        let mut method_signatures: Vec<(String, Vec<metadata::Type>, metadata::Type)> = Vec::new();
125	
126	        for method in &item.methods {
127	            let mut params = vec![];
128	
129	            if method.sig.inputs.is_empty() {
130	                return self.err(&method.sig.ident, "`&self` parameter not found");
131	            }
132	
133	            for (sequence, arg) in method.sig.inputs.iter().enumerate() {
134	                match arg {
135	                    syn::FnArg::Receiver(receiver) => {
136	                        if *receiver != syn::parse_quote! { &self } {
137	                            return self.err(receiver, "`&self` parameter not found");
138	                        }
139	                    }
140	                    syn::FnArg::Typed(pt) => {
141	                        if sequence == 0 {
142	                            return self.err(arg, "`&self` parameter not found");
143	                        }
144	                        let p = self.param(pt)?;
145	                        if item.winrt {
146	                            self.validate_type_is_winrt(&pt.ty, &p.ty)?;
147	                        }
148	                        params.push(p);
149	                    }
150	                }
151	            }
152	
153	            let types: Vec<metadata::Type> = params.iter().map(|param| param.ty.clone()).collect();
154	            let return_type = self.encode_return_type(&method.sig.output)?;
155	
156	            if item.winrt {
157	                if let syn::ReturnType::Type(_, return_syn_ty) = &method.sig.output {
158	                    self.validate_type_is_winrt(return_syn_ty.as_ref(), &return_type)?;
159	                }
160	            }
161	
162	            if !already_has_guid {
163	                method_signatures.push((
164	                    method.sig.ident.to_string(),
165	                    types.clone(),
166	                    return_type.clone(),
167	                ));
168	            }
169	
170	            let signature = metadata::Signature {
171	                flags: metadata::MethodCallAttributes::HASTHIS,
172	                return_type,
173	                types,
174	            };
175	
176	            let mut is_special = false;
177	            for attr in &method.attrs {
178	                if attr.path().is_ident("special") {
179	                    if !matches!(attr.meta, syn::Meta::Path(_)) {
180	                        return self.err(attr, "`special` attribute does not accept arguments");
181	                    }
182	                    is_special = true;
183	                }
184	            }
185	
186	            let mut flags = base_flags;
187	            if is_special {
188	                flags |= metadata::MethodAttributes::SpecialName;
189	            }
190	
191	            let method_def = self.output.MethodDef(
192	                &method.sig.ident.to_string(),
193	                &signature,
194	                flags,
195	                Default::default(),
196	            );
197	
198	            self.encode_attrs(
199	                metadata::writer::HasAttribute::MethodDef(method_def),
200	                &method.attrs,
201	                &["special"],
202	            )?;
203	
204	            self.encode_return_attrs(&method.return_attrs)?;
205	            self.encode_params(&params)?;
206	        }
207	
208	        if !already_has_guid {
209	            let methods: Vec<(&str, &[metadata::Type], &metadata::Type)> = method_signatures
210	                .iter()
211	                .map(|(name, types, ret)| (name.as_str(), types.as_slice(), ret))
212	                .collect();
213	
214	            guid::derive_and_emit_guid(
215	                self.output,
216	                metadata::writer::HasAttribute::TypeDef(interface),
217	                self.namespace,
218	                self.name,
219	                &methods,
220	            );
221	        }
