    /// Emits a single synthesized accessor method (getter/setter/add/remove) with the
    /// `SpecialName` flag set.  `params` are encoded with [`Self::encode_simple_params`] and
    /// the method is recorded for GUID derivation when the interface has no explicit GUID.
    fn encode_accessor(
        &mut self,
        name: &str,
        params: &[(&str, &metadata::Type)],
        return_type: metadata::Type,
        base_flags: metadata::MethodAttributes,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
        already_has_guid: bool,
    ) -> Result<(), Error> {
        let types: Vec<metadata::Type> = params.iter().map(|(_, ty)| (*ty).clone()).collect();

        if !already_has_guid {
            method_signatures.push((name.to_string(), types.clone(), return_type.clone()));
        }

        let signature = metadata::Signature {
            flags: metadata::MethodCallAttributes::HASTHIS,
            return_type,
            types,
        };

        self.output.MethodDef(
            name,
            &signature,
            base_flags | metadata::MethodAttributes::SpecialName,
            Default::default(),
        );

        self.encode_simple_params(params)?;

        Ok(())
    }

    /// Encodes a property shorthand into a getter and/or setter pair.
    fn encode_property(
        &mut self,
        property: &Property,
        winrt: bool,
        base_flags: metadata::MethodAttributes,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
        already_has_guid: bool,
    ) -> Result<(), Error> {
        let mut has_get = false;
        let mut has_set = false;

        for attr in &property.attrs {
            if attr.path().is_ident("get") {
                has_get = true;
            } else if attr.path().is_ident("set") {
                has_set = true;
            }
        }

        // With no attribute a property is read-write; `#[get]`/`#[set]` narrow it.
        let both = !has_get && !has_set;
        let generate_get = has_get || both;
        let generate_set = has_set || both;

        let ty = self.encode_type(&property.ty)?;
        if winrt {
            self.validate_type_is_winrt(&property.ty, &ty)?;
        }

        let name = property.name.to_string();

        if generate_get {
            self.encode_accessor(
                &format!("get_{name}"),
                &[],
                ty.clone(),
                base_flags,
                method_signatures,
                already_has_guid,
            )?;
        }

        if generate_set {
            self.encode_accessor(
                &format!("put_{name}"),
                &[("value", &ty)],
                metadata::Type::Void,
                base_flags,
                method_signatures,
                already_has_guid,
            )?;
        }

        Ok(())
    }

    /// Encodes an event shorthand into an `add_`/`remove_` method pair.
    fn encode_event(
        &mut self,
        event: &Event,
        winrt: bool,
        base_flags: metadata::MethodAttributes,
        method_signatures: &mut Vec<(String, Vec<metadata::Type>, metadata::Type)>,
        already_has_guid: bool,
    ) -> Result<(), Error> {
        let handler_ty = self.encode_type(&event.handler_ty)?;
        if winrt {
            self.validate_type_is_winrt(&event.handler_ty, &handler_ty)?;
        }

        let token_ty = metadata::Type::value_named("Windows.Foundation", "EventRegistrationToken");
        let name = event.name.to_string();

        self.encode_accessor(
            &format!("add_{name}"),
            &[("handler", &handler_ty)],
            token_ty.clone(),
            base_flags,
            method_signatures,
            already_has_guid,
        )?;

        self.encode_accessor(
            &format!("remove_{name}"),
            &[("token", &token_ty)],
            metadata::Type::Void,
            base_flags,
            method_signatures,
            already_has_guid,
        )?;

